// Project configured packages' exported store facets into literal imports.
// This is pure: gen.ts reads the manifests and owns the generated file.
import { type Config, facetsOf, used } from '@yaks/host/config'
import type { FacetName } from '@yaks/host'

export type Manifest = {
  name?: string
  exports?: string | Record<string, string>
}

// Stores serve a graph and its effects. HTTP and long-running services belong
// to their concrete hosts, so those facets never enter this import table.
let facets: FacetName[] = ['vocab', 'graph', 'effects', 'tools']

export let imports = (configs: Config[], manifests: Manifest[]): string[] => {
  let packages = new Map(manifests.map((m) => [m.name, m.exports]))
  let entries = configs.flatMap((c) => c.plugins ?? [])
  let plugins = new Set(entries.map(used))
  return [...plugins].sort().flatMap((plugin) => {
    if (!packages.has(plugin)) throw new Error(`no manifest for ${plugin}`)
    let exported = packages.get(plugin)
    return facets.filter((facet) =>
      entries.some((entry) =>
        used(entry) == plugin &&
        (facetsOf(entry) === undefined || facetsOf(entry)!.includes(facet))
      ) &&
      typeof exported == 'object' && Object.hasOwn(exported, `./${facet}`)
    ).map((facet) => `${plugin}/${facet}`)
  })
}

// The `facet` of each plugin `config` names, refused for one exporting none.
let each = (config: Config, manifests: Manifest[], facet: string) =>
  [...new Set((config.plugins ?? []).map(used))].sort().map((plugin) => {
    let exported = manifests.find((m) => m.name == plugin)?.exports
    if (typeof exported != 'object' || !Object.hasOwn(exported, `./${facet}`)) {
      throw new Error(`${plugin} exports no ./${facet}`)
    }
    return `${plugin}/${facet}`
  })

/** The `./provider` facet of each plugin a provider config names
 * (config.ts `providing`, `serving`): one it names that serves no models is
 * refused. */
export let providers = (config: Config, manifests: Manifest[]): string[] =>
  each(config, manifests, 'provider')

/** The `./graph` facet of each plugin a lending config names (config.ts
 * `embedding`), which `loader` imports with the Worker so a store is lent what
 * they make as it opens: one exporting none is refused. */
export let lenders = (config: Config, manifests: Manifest[]): string[] =>
  each(config, manifests, 'graph')

/** Every package's `./vocab`, configured or not: an app names any of them as a
 * `"platform"` dependency, and its store speaks their words (vocab.ts
 * `lent`). A Worker cannot import a facet it was not bundled with. */
export let vocabs = (manifests: Manifest[]): string[] =>
  manifests.filter((m) =>
    m.name?.startsWith('@yaks/') && typeof m.exports == 'object' &&
    Object.hasOwn(m.exports, './vocab')
  ).map((m) => `${m.name}/vocab`)

export let loader = (
  specifiers: string[],
  local: Record<string, string> = {},
  lending: string[] = [],
): string => {
  let eager = (suffix: string) =>
    specifiers.filter((s) => s.endsWith(suffix)).sort()
  let vocabs = eager('/vocab'), served = eager('/provider')
  let other = specifiers.filter((s) =>
    !s.endsWith('/vocab') && !s.endsWith('/provider')
  )
  return [
    "// Generated by gen.ts from config.ts and the packages' exports. Do not edit.",
    "import type { Facets, Load, VocabFacet } from '@yaks/host'",
    "import type { ProviderFacet } from '@yaks/model'",
    ...vocabs.map((s, i) =>
      `import * as vocab${i} from ${JSON.stringify(local[s] ?? s)}`
    ),
    ...served.map((s, i) =>
      `import * as provider${i} from ${JSON.stringify(local[s] ?? s)}`
    ),
    ...lending.map((s, i) =>
      `import * as lender${i} from ${JSON.stringify(local[s] ?? s)}`
    ),
    'export let vocabFacets: Record<string, VocabFacet> = {',
    ...vocabs.map((s, i) => `${JSON.stringify(s.slice(0, -6))}: vocab${i},`),
    '}',
    '/** The providers config.ts `providing` and `serving` name, by plugin. */',
    'export let providerFacets: Record<string, ProviderFacet> = {',
    ...served.map((s, i) => `${JSON.stringify(s.slice(0, -9))}: provider${i},`),
    '}',
    '/** The graph facets config.ts `embedding` names, by plugin. */',
    "export let lenderFacets: Record<string, Facets['graph']> = {",
    ...lending.map((s, i) => `${JSON.stringify(s.slice(0, -6))}: lender${i},`),
    '}',
    'let facets: Record<string, () => Promise<unknown>> = {',
    ...other.map((s) =>
      `${JSON.stringify(s)}: () => import(${JSON.stringify(local[s] ?? s)}),`
    ),
    '}',
    'export let load: Load = async (plugin, facet) => {',
    "if (facet == 'vocab') return vocabFacets[plugin] ?? null",
    'let take = facets[`${plugin}/${facet}`]',
    'return take ? await take() as Facets[typeof facet] : null',
    '}',
    '',
  ].join('\n')
}
